CREATE OR REPLACE FUNCTION public.guard_reservation_guest_identity() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='INSERT' THEN IF new.guest_user_id IS NOT NULL AND current_user NOT IN ('postgres','service_role') THEN RAISE EXCEPTION 'Guest account linkage requires the guest request function'; END IF; ELSIF new.guest_user_id IS DISTINCT FROM old.guest_user_id THEN RAISE EXCEPTION 'Guest account cannot be reassigned'; END IF; RETURN new; END $$;
CREATE TRIGGER guard_reservation_guest_insert BEFORE INSERT ON public.owner_reservations FOR EACH ROW EXECUTE FUNCTION public.guard_reservation_guest_identity();